  "loc.enterInternetConnectionsAddress": "Jako server zadej adresu svého internetového připojení (např. adresu MyFRITZ!) – obvykle SMS příkazem podle návodu k trackeru.",
  "loc.enterShopAddressesUnder": "Adresy obchodů zadáš v části Seznamy → Upravit nákupní seznam – pokud obchod existuje víckrát, i více popoboček. Když tam někdo chvíli zůstane, naplánovaný nákup se odškrtne.",
