  "loc.fields": "Pole: {felder}",
  "loc.fromPinn": "z pinn.",
  "loc.fromTraccar": "z „Traccar Client“",
  "loc.gettingLocation": "Zjišťuje se poloha …",
  "loc.gpsTracker": "🛰️ GPS tracker",
  "loc.guide1": "Nainstaluj aplikaci <b>„Traccar Client“</b> (App Store nebo Google Play, zdarma).",
  "loc.guide2": "V aplikaci zadej do pole <b>Device ID</b> (identifikátor zařízení):",
  "loc.guide3": "Do pole <b>Server URL</b> zadej:",
  "loc.guide4": "Přesnost <b>Medium</b>, vzdálenost <b>50 m</b>. Aplikace pak odesílá jen při pohybu – ve stoje nic. Pokud máš další pole (interval, heartbeat), nastav heartbeat na vypnuto nebo 0.",
  "loc.guide5": "Povol přístup k poloze: <b>Vždy</b> a <b>Přesná poloha</b> zapnuto.",
  "loc.guide6": "Zapni přepínač <b>Service / Tracking</b> a <b>nech ho stále zapnutý</b> – hotovo. Od teď vše ovládáš v pinn.: „Odesílat trvale“ zapnuto nebo vypnuto, „Odeslat jednou“ a SOS. Dokud je „Odesílat trvale“ vypnuto, nikdo tvou polohu nevidí a pinn. nezaznamenává žádnou trasu.",
  "loc.guideIntro": "I bez další aplikace funguje „📍 Sdílet polohu“ přímo v pinn. – ale jen dokud je pinn. otevřený. Aby poloha docházela i při zavřeném pinn. a zamčené obrazovce, odesílá ji bezplatná aplikace „Traccar Client“ přímo do pinn. (není potřeba žádný server Traccar). Stejně pro iPhone i Android.",
  "loc.h025013Watch5093": ", H02 5013, Watch 5093, Teltonika 5027. Tento port musí být v FRITZ!Boxu přesměrován na NAS, protože tracker se připojuje z mobilní sítě.",
