  "loc.setup": "Nastavení · {famDeviceName}",
  "loc.setupIntro": "Telefony nic dalšího nepotřebují: každý může sdílet přímo v pinn. v části „Moje poloha“. Na pozadí (pinn. zavřený) telefon odesílá bezplatnou aplikací „Traccar Client“ (iPhone i Android) – přímo do pinn., žádný server Traccar není potřeba. Kontejner „traccar“ potřebují jen GPS trackery se SIM kartou (např. na obojku). Polohy zůstávají na tvém NAS.",
