  "loc.traccarClientChooseSend": "V „Traccar Client“ zvol „Send SOS“ (podle verze v aplikaci nebo dlouhým stisknutím ikony aplikace). pinn. okamžitě upozorní všechny členy rodiny pushem – s polohou, adresou, časem a tlačítky pro volání a tísňovou linku {regionNotrufText}. Tip: zadej své číslo mobilu do nouzové karty.",
